text = open(src, encoding='utf-8').read().splitlines()
people, era = [], None
for ln in text:
    s = ln.strip()
    if not s:
        continue
    for prefix, eid, label in ERA_IDS:
        if s.startswith(prefix):
            era = {'id': eid, 'title': s, 'short': label}
            break
    else:
        m = re.match(r'^(.+?)\s*\(([^)]*)\)\s*:\s*(.+)$', s)
        if m and era:
            people.append({'th': m.group(1).strip(), 'en': m.group(2).strip(), 'role': m.group(3).strip(), 'era': era['id']})

assert len(people) == len(EXTRA) == 100, (len(people), len(EXTRA))
eras = []
for prefix, eid, label in ERA_IDS:
    title = next(ln.strip() for ln in text if ln.strip().startswith(prefix))
    testament = 'new' if eid in ('gospels', 'church') else 'old'
    eras.append({'id': eid, 'title': title, 'short': label, 'testament': testament})

ids = set()
for i, (p, (pid, refs, themes, lesson)) in enumerate(zip(people, EXTRA), 1):
    assert pid not in ids, pid
    ids.add(pid)
    p.update({'id': pid, 'order': i, 'refs': refs, 'themes': themes, 'lesson': lesson, 'review_status': 'draft'})

all_themes = sorted({t for p in people for t in p['themes']})
for sit, ts in SITUATION_THEMES.items():
    for t in ts:
        assert t in all_themes, (sit, t)
